import * as THREE from "three";

import { Solution } from "../";
import { ThreeCore } from '../ThreeCore';

import { Hypercube } from "./HyperCube";

import { getGround, loadFBX, createStudioEnvironment } from "../Utils";

export class AppCore {
  public solution: Solution;
  public threeCore: ThreeCore;
  public scene: THREE.Scene;
  public boxMeshes: THREE.Mesh[] = [];

  public hyperCube: Hypercube;

  meshDoorLeft: THREE.Mesh = undefined;
  meshDoorRight: THREE.Mesh = undefined;

  public meshGround: THREE.Mesh = undefined;
  public meshSphere: THREE.Mesh = undefined;

  selectedMesh: THREE.Object3D | undefined = undefined

  constructor(solution: Solution, sphereNeeded = false) {
    this.solution = solution;
    this.threeCore = solution.threeCore;
    this.scene = solution.threeCore.scene;

    this.init();
  }
  public init() {
    this.meshGround = getGround();
    this.scene.add(this.meshGround);

    this.meshSphere = createStudioEnvironment();
    this.scene.add(this.meshSphere);

    this.hyperCube = new Hypercube(this);
  }
  public loaded() {
    this.threeCore.loaded = true;
  }
  public update() {
    this.hyperCube.update();
  }
  public mouseDown(e: MouseEvent) {
    const mesh = onClick(this, e);
    this.selectedMesh = mesh
    // console.log(mesh.name, e, "core");
    if (mesh.name === "mesh11848" || mesh.name === "Object991") {
      this.hyperCube.clickDoorInner();
    }
    if (mesh.name === "Object981") {
      this.hyperCube.clickDoorOuter();
    }
    if (mesh.name ==='Object984') {
      this.hyperCube.showCamera();
    }
    if (mesh.name ==='Object987') {
      this.hyperCube.showGraph();
    }
    if (mesh.name ==='Object996') {
      this.hyperCube.showGraphDrone();
    }
    

  }
  public mouseUp(e: MouseEvent) {
    // console.log(e, 'core');
  }
  public mouseMove(e: MouseEvent) {
    // console.log(e, 'core');
  }
  public mouseDrag(e: MouseEvent) {
    // console.log(e, 'core');
  }
  public destroy() {}
  public showFloor(v) {
    this.meshGround.visible = v;
    this.meshSphere.visible = v;
  }
}

const onClick = (core: AppCore, event) => {
  const raycaster = new THREE.Raycaster();
  const mouse = new THREE.Vector2();

  mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
  mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

  raycaster.setFromCamera(mouse, core.threeCore.cameraWrapper.camera);

  const intersects = raycaster.intersectObjects(
    core.threeCore.scene.children,
    true
  );

    const visibleIntersects = intersects.filter((i) => i.object.visible);
  console.log(visibleIntersects)
  if (visibleIntersects.length > 0) {
    const selectedObject = visibleIntersects[0].object;
    // console.log("Selected object:", selectedObject);

    console.log("Name:", selectedObject.name);
    // console.log("position:", selectedObject.position);
    // console.log("scale:", selectedObject.scale);
    // console.log("Material:", selectedObject.material);
    // selectedObject.position.y += 100;

    if (selectedObject.name === 'ground') {
      return undefined
    }
    return selectedObject;
  } else {
    // console.log("noting selected");
    return undefined;
  }
};
