import * as THREE from "three";

import { RGBELoader } from "three/examples/jsm/loaders/RGBELoader";
import { PMREMGenerator } from "three";
import { EffectComposer } from "three/examples/jsm/postprocessing/EffectComposer.js";
import { RenderPass } from "three/examples/jsm/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/examples/jsm/postprocessing/UnrealBloomPass.js";
import { SSAOPass } from "three/examples/jsm/postprocessing/SSAOPass.js";

import { CopyShader } from "three/examples/jsm/shaders/CopyShader.js";
import { ShaderPass } from "three/examples/jsm/postprocessing/ShaderPass.js";
import { BokehPass } from "three/examples/jsm/postprocessing/BokehPass";

import { getDirectionalLight, createStudioEnvironment } from "../Utils";
import { CameraWrapper } from "./CameraWrapper";

export class ThreeCore {
  public canvas: HTMLCanvasElement;
  public host: HTMLElement;
  public ctx: CanvasRenderingContext2D;
  public t: number = 0.0;

  public scene: THREE.Scene;
  public renderer: THREE.WebGLRenderer;
  public requestFrame: number;
  public composer: EffectComposer;

  public loaded = false;
  public solar = undefined;

  public cameraWrapper: CameraWrapper;

  private skyMesh = undefined;
  private currentEnvironmentMap = undefined;

  private needPostProcessing = false;

  constructor(id: string) {
    this.initCanvas(id);
  }
  public async initCanvas(id: string) {
    THREE.Object3D.DEFAULT_UP.set(0, 0, 1);

    this.host = document.getElementById(id);

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0, 0, 0);
    this.scene.castShadow = true;

    this.renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: false,
      powerPreference: "high-performance",
    });
    this.renderer.setPixelRatio(this.host.clientWidth / this.host.clientHeight);
    this.renderer.domElement.id = "Three";

    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.2;
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.localClippingEnabled = true;

    this.renderer.setSize(this.host.clientWidth, this.host.clientHeight);
    this.host.appendChild(this.renderer.domElement);

    this.scene.background = new THREE.Color(0xffffff);
    // this.scene.background = new THREE.Color(0x000000);

    this.cameraWrapper = new CameraWrapper(this);

    await this.initHDRI("bridge.hdr");

    this.solar = getDirectionalLight();
    this.scene.add(this.solar);
    // const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    // ambientLight.castShadow = true;
    // this.scene.add(ambientLight);

    // const pointLight = new THREE.PointLight(0xffffff, 100);
    // pointLight.position.x = 10;
    // pointLight.castShadow = true;
    // this.scene.add(pointLight);

    const hemiLight = new THREE.HemisphereLight(0xffffff, 0x444444, 0.5);
    hemiLight.position.set(0, 10, 0);
    this.scene.add(hemiLight);

    if (this.needPostProcessing) {
      this.initPostProcessing();
    }

    this.eventBind();
    this.loop();
  }
  async initHDRI(name = "") {
    const loader = new RGBELoader();
    const pmremGenerator = new PMREMGenerator(this.renderer);
    pmremGenerator.compileEquirectangularShader();

    try {
      if (this.skyMesh) {
        this.scene.remove(this.skyMesh);
        this.skyMesh.geometry.dispose();
        this.skyMesh.material.map?.dispose();
        this.skyMesh.material.dispose();
        this.skyMesh = undefined;
      }

      if (this.currentEnvironmentMap) {
        this.currentEnvironmentMap.dispose();
        this.currentEnvironmentMap = undefined;
      }

      if (!name) {
        this.scene.environment = null;
        return;
      }

      const path = process.env.PUBLIC_URL + "/static/data/model/map/" + name;
      const hdrEquirect = await loader.loadAsync(path);
      hdrEquirect.mapping = THREE.EquirectangularReflectionMapping;

      const envMap = pmremGenerator.fromEquirectangular(hdrEquirect).texture;
      this.scene.environment = envMap;
      this.currentEnvironmentMap = envMap;

      const skyGeo = new THREE.SphereGeometry(2000, 60, 40);
      const skyMat = new THREE.MeshBasicMaterial({
        map: hdrEquirect,
        side: THREE.BackSide,
      });
      const skyMesh = new THREE.Mesh(skyGeo, skyMat);
      skyMesh.rotation.x = Math.PI / 2;
      this.scene.add(skyMesh);
      this.skyMesh = skyMesh;

      hdrEquirect.dispose();
      pmremGenerator.dispose();
    } catch (error) {
      console.error("HDRI, fail to load:", error);
    }
  }

  public initPostProcessing() {
    const composer = new EffectComposer(this.renderer);
    composer.addPass(new RenderPass(this.scene, this.cameraWrapper.camera));

    // const bloomPass = new UnrealBloomPass(
    //   new THREE.Vector2(window.innerWidth, window.innerHeight),
    //   0.05,
    //   0.5,
    //   0.2
    // );
    // composer.addPass(bloomPass);

    // const composer = new EffectComposer(renderer);
    // composer.addPass(new RenderPass(scene, camera));

    const bokehPass = new BokehPass(this.scene, this.cameraWrapper.camera, {
      focus: 200, // 초점 거리
      aperture: 0.0001, // 조리개 (작을수록 선명, 클수록 흐림)
      maxblur: 8.0, // 최대 블러 세기

      width: this.renderer.domElement.width,
      height: this.renderer.domElement.height,
    });
    composer.addPass(bokehPass);



    // const width = this.host.clientWidth;
    // const height = this.host.clientHeight;

    // const depthTexture = new THREE.DepthTexture(width, height);
    // depthTexture.type = THREE.UnsignedShortType;

    // const renderTarget = new THREE.WebGLRenderTarget(width, height, {
    //   format: THREE.RGBAFormat,
    //   depthBuffer: true,
    //   depthTexture,
    // });

    // const composer = new EffectComposer(this.renderer, renderTarget);
    // composer.setSize(width, height);
    // composer.addPass(new RenderPass(this.scene, this.cameraWrapper.camera));

    // const ssaoPass = new SSAOPass(
    //   this.scene,
    //   this.cameraWrapper.camera,
    //   width,
    //   height
    // );
    // ssaoPass.kernelRadius = 500;
    // ssaoPass.minDistance = 5;
    // ssaoPass.maxDistance = 1500;
    // ssaoPass.output = SSAOPass.OUTPUT.Default;
    // composer.addPass(ssaoPass);

    // const copyPass = new ShaderPass(CopyShader);
    // copyPass.renderToScreen = true;
    // composer.addPass(copyPass);
    
    this.composer = composer;
  }
  public eventBind() {
    this.renderer.domElement.onmousedown = (e: MouseEvent) => this.MouseDown(e);
    this.renderer.domElement.onmouseup = (e: MouseEvent) => this.MouseUp(e);
    this.renderer.domElement.onmousemove = (e: MouseEvent) => this.MouseMove(e);

    window.addEventListener("resize", () => this.onWindowResize());
    // this.host.addEventListener('resize', () => this.onWindowResize() );

    // window.addEventListener('click', onClick, false);
  }
  private onWindowResize() {
    this.cameraWrapper.onWindowResize();

    this.renderer.setSize(this.host.clientWidth, this.host.clientHeight);
  }
  public MouseDown(e: MouseEvent) {
    // console.log(e);
    // onClick(e);
  }
  public MouseUp(e: MouseEvent) {
    console.log(e);
  }
  public MouseMove(e: MouseEvent) {
    console.log(e);
  }
  public loop = () => {
    this.requestFrame = requestAnimationFrame(this.loop);

    if (this.loaded) {
      // console.log('rendering...')
      this.cameraWrapper.update();
      this.update();

      if (this.needPostProcessing) {
        this.composer.render();
      } else {
        this.renderer.render(this.scene, this.cameraWrapper.camera);
      }

      // console.log('working');

      this.t += 0.01;
    }
  };
  public update() {}
  public destroy() {
    window.removeEventListener("resize", () => this.onWindowResize());
    cancelAnimationFrame(this.requestFrame);
    this.requestFrame = undefined;
    while (this.host.lastChild) {
      this.host.removeChild(this.host.lastChild);
    }
  }
  public showEnv() {}
}
