import { NSolar } from "lib/NJSCore";
import { Solution } from "..";
import { v1 } from "firebase-admin/firestore";

export class AppCommon {
  public solution: Solution;

  public solar: NSolar;

  private _showEnv = true;

  private _sampleCameraPositionIndex = 0;
  private _sampleCameraPosition = [
    [100, -100, 100],
    [100, 100, 100],
    [0, -120, 50],
    [0, -120, 0],
    [0, 0, 120],
  ];

  private _sampleHDRIIndex = 0;
  private _sampleHDRI = [
    "",
    "bridge.hdr",
    "controlroom.hdr",
    "VizPeople_non_commercial_hdr_v1_03.hdr",
  ];

  constructor(solution: Solution) {
    this.solution = solution;

    this.solar = new NSolar();
  }
  public get showEnv() {
    return this._showEnv;
  }
  public set showEnv(v: boolean) {
    this._showEnv = v;
    this.solution.threeCore.showEnv();
    this.solution.appCore.showFloor(this._showEnv);
  }
  public get runningDroneDevices() {
    return this.solution.appCore.hyperCube.runningDroneDevices;
  }
  public set runningDroneDevices(v: boolean) {
    this.solution.appCore.hyperCube.runningDroneDevices = v;
  }
  public angleSolarPanel(v) {
    this.solution.appCore.hyperCube.angleSolarPanel = v
  }
  public viewChanging() {
    const vec =
      this._sampleCameraPosition[
        this._sampleCameraPositionIndex++ % this._sampleCameraPosition.length
      ];
    this.solution.threeCore.cameraWrapper.move(vec[0], vec[1], vec[2]);
  }
  public decompose() {
    this.solution.appCore.hyperCube.decompose();
  }
  public hdriChanging() {
    const val =
      this._sampleHDRI[this._sampleHDRIIndex++ % this._sampleHDRI.length];
    this.solution.threeCore.initHDRI(val);
  }
  public getSunVec(Latitude: number, theDay: number, Hour) {
    // 30.23, Day: 100, Hour: 13
    const scale = 100;
    this.solar.Update(Latitude, theDay, Hour);

    // this.solution.threeCore.solar.position.set(
    //   this.solar.VectorSun.x * scale,
    //   this.solar.VectorSun.y * scale,
    //   this.solar.VectorSun.z * scale
    // );

    this.solution.threeCore.solar.position.x = this.solar.VectorSun.x * scale;
    this.solution.threeCore.solar.position.y = this.solar.VectorSun.y * scale;
    this.solution.threeCore.solar.position.z = this.solar.VectorSun.z * scale;

    this.solution.view.metadataPosition.textContent = `Latitude: ${this.solar.latitude}, Day: ${this.solar.day}, Hour: ${this.solar.hour}`;
  }
  public debuggerX(value) {
    // console.log("x: ", value);
    if(this.solution.appCore.selectedMesh) {
      this.solution.appCore.selectedMesh.position.x =value;
    }
  }
  public debuggerY(value) {
    // console.log("y: ", value);
    if(this.solution.appCore.selectedMesh) {
      this.solution.appCore.selectedMesh.position.z =value;
    }
  }
  public debuggerZ(value) {
    // console.log("z: ", value);
    if(this.solution.appCore.selectedMesh) {
      this.solution.appCore.selectedMesh.position.y =value;
    }
  }
}
