import { ThreeCore } from "./ThreeCore";
import { AppCore } from "./AppCore";
import { View } from "./View";
import { AppCommon } from './AppCommon';

export class Solution {
  public view: View;
  public threeCore: ThreeCore;
  public appCore: AppCore;
  public appCommon: AppCommon;
  static Init(id: string) {
    const app = new Solution(id);
    return app;
  }
  constructor(id: string = "main") {
    this.threeCore = new ThreeCore(id);
    this.appCore = new AppCore(this);
    this.appCommon = new AppCommon(this);
    this.view = new View(this);
    this.bindEvent();
    this.bindRenderer();

  }
  public bindEvent() {
    this.threeCore.MouseDown = (e: MouseEvent) => this.appCore.mouseDown(e);
    this.threeCore.MouseMove = (e: MouseEvent) => this.appCore.mouseMove(e);
    this.threeCore.MouseUp = (e: MouseEvent) => this.appCore.mouseUp(e);
  }
  public bindRenderer() {
    this.threeCore.update = () => this.appCore.update();
  }
  public destroy() {
    this.view.destroy();
    this.appCore.destroy();
    this.threeCore.destroy();
  }
}
