    divTitleMeta.textContent = "Latitude: 30.23, Day: 286, Hour: 14";
    divTitleMeta.style.fontSize = "20px";
    divTitleMeta.style.width = "100%";
    divTitleMeta.style.height = "100px";
    divTitleMeta.style.paddingTop = "45px";
    divTitleMeta.style.position = "absolute";
    divTitleMeta.style.textAlign = "center";
    divTitleMeta.style.zIndex = "10";
    divTitleMeta.style.pointerEvents = 'none'
    this.solution.appCore.threeCore.host.appendChild(divTitleMeta);

