    const divBt1 = document.createElement("button");
    divUI.appendChild(divBt1);
    divBt1.style.width = width;
    divBt1.textContent = "changing views";
    divBt1.onclick = () => {
      this.solution.appCommon.viewChanging();
    };

    const divBt2 = document.createElement("button");
    divUI.appendChild(divBt2);
    divBt2.style.width = width;
    divBt2.textContent = "toggle env";
    divBt2.onclick = () => {
      this.solution.appCommon.showEnv = !this.solution.appCommon.showEnv;
    };

    const divBt3 = document.createElement("button");
    divUI.appendChild(divBt3);
    divBt3.style.width = width;
